\begin{tikzpicture}[x=1cm,y=1cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-4.6,-4.7) rectangle (4.6,3.5);
\draw[black,line width=0.5pt,->] (-4.25,0)--(4.25,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3.2)--(0,3.2) node[above] {$y$};
\draw[black,line width=0.4pt,dashed] (-2,-1)--(2,-1) (-2,1)--(2,1) (-2,-1)--(-2,1) (2,-1)--(2,1);
\foreach \x in {-2,-1,1,2}{\draw[black,line width=0.4pt] (\x,0.06)--(\x,-0.06);\node[below,fill=white,inner sep=1pt] at (\x,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\x$\special{dvisvgm:raw </g>}};}
\foreach \y in {-1,1}{\node[left,fill=white,inner sep=1pt] at (-0.06,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};}
\draw[black,line width=0.8pt,<->] plot[domain=0.125:4,samples=160] (\x,{ln(\x)/ln(2)});
\draw[black,line width=0.8pt,dashed,<->] plot[domain=0.125:4,samples=160] (\x,{-ln(\x)/ln(2)});
\draw[black,line width=0.8pt,dash dot,<->] plot[domain=-4:-0.125,samples=160] (\x,{ln(-\x)/ln(2)});
\draw[black,line width=0.8pt,densely dotted,<->] plot[domain=-4:-0.125,samples=160] (\x,{-ln(-\x)/ln(2)});
\draw[black,line width=0.8pt] (-4.2,-3.65)--(-3.5,-3.65);\node[anchor=west] at (-3.3,-3.65) {$y=\log_2 x$};
\draw[black,line width=0.8pt,dashed] (0.2,-3.65)--(0.9,-3.65);\node[anchor=west] at (1.1,-3.65) {$y=-\log_2 x$};
\draw[black,line width=0.8pt,dash dot] (-4.2,-4.35)--(-3.5,-4.35);\node[anchor=west] at (-3.3,-4.35) {$y=\log_2(-x)$};
\draw[black,line width=0.8pt,densely dotted] (0.2,-4.35)--(0.9,-4.35);\node[anchor=west] at (1.1,-4.35) {$y=-\log_2(-x)$};
\end{tikzpicture}
